def evaluate(current_reputation, observation, my_history, round_num):
    # Weighted average of own actions (all history, exponential decay)
    coop_score = 0.0
    total_weight = 0.0
    decay = 0.9
    weight = 1.0
    # Process from most recent to oldest (excluding current)
    for entry in reversed(my_history):
        if entry['action'] == 'cooperate':
            coop_score += weight * 1.0
        else:
            coop_score += weight * -1.0
        total_weight += weight
        weight *= decay
    # Include current round's action from observation
    if observation['action'] == 'cooperate':
        coop_score += 1.0
    else:
        coop_score += -1.0
    total_weight += 1.0
    # Normalize to [-1, 1]
    if total_weight > 0:
        rep = coop_score / total_weight
    else:
        rep = 0.0
    return max(-1.0, min(1.0, rep))

def decide(recipient_reputation, round_num, my_history):
    # Use own recent cooperation rate to adjust threshold
    recent_own = [e for e in my_history[-5:] if e is not None]
    if recent_own:
        coop_count = sum(1 for e in recent_own if e['action'] == 'cooperate')
        own_rate = coop_count / len(recent_own)
    else:
        own_rate = 0.5  # neutral default
    # Threshold: more forgiving when own recent cooperativeness is high
    threshold = 0.2 - own_rate * 0.3
    return recipient_reputation > threshold

